import itertools, json
jobs='ABCDE'
slot=dict(zip(jobs,[(10,7,11,4,4),(3,1,1,4,8),(5,4,5,6,2),(3,3,7,1,11),(10,9,10,1,9)]))
transfer=dict(zip(jobs,[(0,3,3,5,0),(5,0,3,2,0),(5,3,0,2,1),(4,2,4,0,5),(1,5,4,1,0)]))
def nominal(p):
    return sum(slot[j][i] for i,j in enumerate(p))+sum(transfer[a][jobs.index(b)] for a,b in zip(p,p[1:]))
def legal(p,s):
    if p.index('A')>p.index('D'): return False
    return {'rain':p[4]!='C' and p[0]!='A','road':p[0]!='B' and p[1]!='C','lift':p[4] not in 'DB'}[s]
def penalty(p,s):
    return {'rain':8*max(0,p.index('E')), 'road':5*max(0,p.index('D')-2), 'lift':5*max(0,p.index('E')-1)}[s]
def neighbors(p):
    yield p,0
    for i,j in itertools.combinations(range(5),2):
        q=list(p); q[i],q[j]=q[j],q[i]
        yield ''.join(q),1
scenarios=('rain','road','lift')
rows=[]
for t in itertools.permutations(jobs):
    p=''.join(t)
    if p.index('A')>p.index('D'): continue
    opts={s:sorted((nominal(q)+penalty(q,s)+swap,q) for q,swap in neighbors(p) if legal(q,s)) for s in scenarios}
    if all(opts.values()):
        best={s:opts[s][0] for s in scenarios}
        rows.append((nominal(p)+max(c for c,q in best.values()),p,best))
rows.sort()
score,p,best=rows[0]
answer={'roster':p,'score':score,'repairs':{s:best[s][1] for s in scenarios},'repair_costs':{s:best[s][0] for s in scenarios},'feasible_count':len(rows),'next_score':min(v for v,_,_ in rows if v>score)}
# Independent scan: all legal finals, using Hamming distance to identify one exchange.
allp=[''.join(t) for t in itertools.permutations(jobs) if t.index('A')<t.index('D')]
def direct_base(q):
    total=0
    for k in range(5): total+=slot[q[k]][k]
    for k in range(4): total+=transfer[q[k]][ord(q[k+1])-65]
    return total
check=[]
for pub in allp:
    minima=[]
    for s in scenarios:
        values=[]
        for q in allp:
            diff=sum(a!=b for a,b in zip(pub,q))
            if diff not in (0,2): continue
            pos={j:q.index(j)+1 for j in jobs}
            if s=='rain':
                if pos['C']==5 or pos['A']==1: continue
                late=8*(pos['E']-1)
            elif s=='road':
                if pos['B']==1 or pos['C']==2: continue
                late=5*max(0,pos['D']-3)
            else:
                if pos['D']==5 or pos['B']==5: continue
                late=5*max(0,pos['E']-2)
            values.append(direct_base(q)+late+int(diff==2))
        if not values: break
        minima.append(min(values))
    if len(minima)==3: check.append((direct_base(pub)+max(minima),pub))
assert sorted(check)==sorted((v,q) for v,q,_ in rows)
payload=json.dumps(answer,separators=(',',':'))
recovered=json.loads(payload)
assert set(recovered)=={'roster','score','repairs','repair_costs','feasible_count','next_score'}
assert recovered['score']==min(v for v,_ in check)
for s in scenarios:
    q=recovered['repairs'][s]
    assert legal(q,s)
    d=sum(a!=b for a,b in zip(p,q))
    assert d in (0,2)
    assert nominal(q)+penalty(q,s)+(d==2)==recovered['repair_costs'][s]==best[s][0]
print(payload)
print('Verified by two enumerations. Published nominal:',nominal(p))
print('Repair nominal/penalty/swap:',{s:(nominal(best[s][1]),penalty(best[s][1],s),int(p!=best[s][1])) for s in scenarios})

