slots=[[10,7,11,4,4],[3,1,1,4,8],[5,4,5,6,2],[3,3,7,1,11],[10,9,10,1,9]]
trans=[[0,3,3,5,0],[5,0,3,2,0],[5,3,0,2,1],[4,2,4,0,5],[1,5,4,1,0]]
def nominal(q):
    return sum(slots[jobs.index(j)][i] for i,j in enumerate(q))+sum(trans[jobs.index(a)][jobs.index(b)] for a,b in zip(q,q[1:]))
def distance(q):
    perm=[pub.index(j) for j in q]; seen=set(); cycles=0
    for i in range(5):
        if i not in seen:
            cycles+=1
            while i not in seen:
                seen.add(i);i=perm[i]
    return 5-cycles
classes={i:[] for i in range(3)}
for t in itertools.permutations(jobs):
    q=''.join(t);d=distance(q)
    if d>2 or q.index('A')>q.index('D') or q[4]=='C' or q[0] in 'AE':continue
    cost=nominal(q)+8*q.index('E')+d+10*(d==2)
    classes[d].append((cost,q))
best=min(x for group in classes.values() for x in group)
a={'roster':best[1],'score':best[0],'best_by_swaps':{str(d):min(v)[0] if v else None for d,v in classes.items()},'feasible_by_swaps':{str(d):len(v) for d,v in classes.items()}}
# Verify minimum distances independently with breadth-first enumeration of exchanges.
dist={pub:0};front=[pub]
for depth in (1,2):
    nxt=[]
    for p in front:
        for i,j in itertools.combinations(range(5),2):
            q=list(p);q[i],q[j]=q[j],q[i];q=''.join(q)
            if q not in dist:dist[q]=depth;nxt.append(q)
    front=nxt
check={d:[] for d in range(3)}
for q,d in dist.items():
    assert distance(q)==d
    pos={j:q.index(j)+1 for j in jobs}
    if pos['A']>=pos['D'] or pos['C']==5 or pos['A']==1 or pos['E']==1:continue
    base=sum(slots[ord(q[k])-65][k] for k in range(5))
    base+=sum(trans[ord(q[k])-65][ord(q[k+1])-65] for k in range(4))
    cost=base+8*(pos['E']-1)+[0,1,12][d]
    check[d].append((cost,q))
assert all(sorted(check[d])==sorted(classes[d]) for d in range(3))
payload=json.dumps(a,separators=(',',':')); decoded=json.loads(payload)
assert decoded['roster']==best[1] and decoded['score']==best[0]
for d in range(3):
    assert decoded['best_by_swaps'][str(d)]==(min(check[d])[0] if check[d] else None)
